mapper.select:
SELECT /* 공통팀 유민상 isry.sample.mapper.SrvcResrceMngMapper.selectSrvcResrceMngList 공통팀 유민상 */ RESRCE_NO /*자원명*/ , PVSN_RESRCE_NM /*제공자원명*/ , RSFR_INST_NO /*자원제공주체코드*/ , (SELECT INST_NM FROM SAA000 WHERE INST_NO = RSFR_INST_NO) AS RSFR_INST_NM /*자원제공주체명(TODO)*/ , SRVC_TYPE_SE_CD /*서비스유형*/ , SRVC_RESRCE_LCLAS_SE_CD /*서비스 자원 대분류*/ , SRVC_RESRCE_MLSFC_SE_CD /*서비스 자원 중분류*/ , SRVC_RESRCE_SCLAS_SE_CD /*서비스 자원 소분류*/ , SRVC_RESRCE_DTL_SE_CD /*서비스 자원 상세*/ , PVSN_BGNG_YMD /*자원제공 시작일자*/ , PVSN_END_YMD /*자원제공 종료일자*/ , AUTZR_NO /*승인자성명(임시 승인자번호)*/ , APRV_DT /*승인일자*/ FROM SDA100 WHERE 1=1
AND PVSN_RESRCE_NM LIKE '%'|| #{PVSN_RESRCE_NM} || '%'
AND PVSN_RESRCE_NM LIKE '%'|| #{PVSN_RESRCE_NM} || '%'
AND PVSN_RESRCE_NM LIKE '%'|| #{PVSN_RESRCE_NM} || '%'
AND RSFR_INST_NO = #{RSFR_INST_NO}
AND SRVC_RESRCE_LCLAS_SE_CD = #{SRVC_RESRCE_LCLAS_SE_CD}
AND SRVC_RESRCE_MLSFC_SE_CD = #{SRVC_RESRCE_MLSFC_SE_CD}
AND SRVC_RESRCE_SCLAS_SE_CD = #{SRVC_RESRCE_SCLAS_SE_CD}
AND SRVC_RESRCE_DTL_SE_CD = #{SRVC_RESRCE_DTL_SE_CD}

mapper.insert:


      SELECT SDA100_SQ01.NEXTVAL AS RESRCE_NO FROM DUAL              



/* 공통팀 유민상 isry.sample.mapper.SrvcResrceMngMapper.insertSrvcResrceMngList 공통팀 유민상 */
INSERT INTO SDA100(
      RESRCE_NO            
    , PVSN_RESRCE_NM
    , RSFR_INST_NO
    , SRVC_TYPE_SE_CD  

    , DPSITR_ANYM_YN


    , DPSITR_NM


    , DPSITR_TELNO


    , SRVC_RESRCE_LCLAS_SE_CD


    , SRVC_RESRCE_MLSFC_SE_CD


    , SRVC_RESRCE_SCLAS_SE_CD


    , SRVC_RESRCE_DTL_SE_CD


    , PVSN_BGNG_YMD


    , PVSN_END_YMD


    , RESRCE_SE_CD


    , RESRCE_RGN_CTPV_SE_CD


    , RESRCE_RGN_SGG_CD


    , GR_TRGT_SRVC_YN


    , APRV_YN


    , APRV_DT


    , APRV_CN


    , RJCT_CS_CN


    , HPGE_URL_ADDR

    , FRST_RGTR_ID    
    , FRST_REG_DT       
    , LAST_MDFR_ID
    , LAST_MDFCN_DT         
)VALUES(
      #{RESRCE_NO}            
    , #{PVSN_RESRCE_NM}
    , #{RSFR_INST_NO}
    , #{SRVC_TYPE_SE_CD}          

    , #{DPSITR_ANYM_YN}


    , #{DPSITR_NM}


    , #{DPSITR_TELNO}


    , #{SRVC_RESRCE_LCLAS_SE_CD}


    , #{SRVC_RESRCE_MLSFC_SE_CD}


    , #{SRVC_RESRCE_SCLAS_SE_CD}


    , #{SRVC_RESRCE_DTL_SE_CD}


    , #{PVSN_BGNG_YMD}


    , #{PVSN_END_YMD}


    , #{RESRCE_SE_CD}


    , #{RESRCE_RGN_CTPV_SE_CD}


    , #{RESRCE_RGN_SGG_CD}


    , #{GR_TRGT_SRVC_YN}


    , #{APRV_YN}


    , #{APRV_DT}


    , #{APRV_CN}


    , #{RJCT_CS_CN}


    , #{HPGE_URL_ADDR}

    , #{FRST_RGTR_ID}
    , SYSDATE
    , #{LAST_MDFR_ID}
    , SYSDATE           
)

mapper.update:
/* isry.sample.mapper.SrvcResrceMngMapper.updateSrvcResrceMngList 공통팀 유민상 */
UPDATE SDA100 SET

      PVSN_RESRCE_NM = #{PVSN_RESRCE_NM}
    , RSFR_INST_NO = #{RSFR_INST_NO}       

    , DPSITR_ANYM_YN = #{DPSITR_ANYM_YN}


    , DPSITR_NM = #{DPSITR_NM}


    , DPSITR_TELNO = #{DPSITR_TELNO}

    , SRVC_TYPE_SE_CD = #{SRVC_TYPE_SE_CD}        

    , SRVC_RESRCE_LCLAS_SE_CD = #{SRVC_RESRCE_LCLAS_SE_CD}


    , SRVC_RESRCE_MLSFC_SE_CD = #{SRVC_RESRCE_MLSFC_SE_CD}


    , SRVC_RESRCE_SCLAS_SE_CD = #{SRVC_RESRCE_SCLAS_SE_CD}


    , SRVC_RESRCE_DTL_SE_CD = #{SRVC_RESRCE_DTL_SE_CD}


    , PVSN_BGNG_YMD = #{PVSN_BGNG_YMD}


    , PVSN_END_YMD = #{PVSN_END_YMD}


    , RESRCE_SE_CD = #{RESRCE_SE_CD}


    , RESRCE_RGN_CTPV_SE_CD = #{RESRCE_RGN_CTPV_SE_CD}


    , RESRCE_RGN_SGG_CD = #{RESRCE_RGN_SGG_CD}


    , GR_TRGT_SRVC_YN = #{GR_TRGT_SRVC_YN}


    , APRV_YN = #{APRV_YN}


    , APRV_DT = #{APRV_DT}


    , APRV_CN = #{APRV_CN}


    , RJCT_CS_CN = #{RJCT_CS_CN}


    , HPGE_URL_ADDR = #{HPGE_URL_ADDR}

    , LAST_MDFCN_DT = SYSDATE     
    , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE 1=1
AND RESRCE_NO = #{RESRCE_NO__origin}

mapper.insert:



      SELECT SDA300_SQ01.NEXTVAL AS PROGRM_NO FROM DUAL              



/* 공통팀 유민상 isry.sample.mapper.SrvcResrceMngMapper.insertSrvcResrceProgramList 공통팀 유민상 */
