    , PROGRM_TTL_NM


    , PROGRM_SE_CD


    , PROGRM_DSCRP_CN


    , PROGRM_DGSTFN_CN


    , PROGRM_BGNG_YMD


    , PROGRM_END_YMD


    , PROGRM_SUM_HR


    , SRVC_RESRCE_LCLAS_SE_CD


    , SRVC_RESRCE_MLSFC_SE_CD 


    , SRVC_RESRCE_SCLAS_SE_CD


    , SRVC_RESRCE_DTL_SE_CD


    , RTRCN_YN

    , FRST_RGTR_ID    
    , FRST_REG_DT       
    , LAST_MDFR_ID
    , LAST_MDFCN_DT         
)VALUES(
      #{RESRCE_NO}            
    , #{PROGRM_NO}

    , #{PROGRM_TTL_NM}


    , #{PROGRM_SE_CD}


    , #{PROGRM_DSCRP_CN}


    , #{PROGRM_DGSTFN_CN}


    , #{PROGRM_BGNG_YMD}


    , #{PROGRM_END_YMD}


    , #{PROGRM_SUM_HR}


    , #{SRVC_RESRCE_LCLAS_SE_CD}


    , #{SRVC_RESRCE_MLSFC_SE_CD} 


    , #{SRVC_RESRCE_SCLAS_SE_CD}


    , #{SRVC_RESRCE_DTL_SE_CD}


    , #{RTRCN_YN}

    , #{FRST_RGTR_ID}
    , SYSDATE
    , #{LAST_MDFR_ID}
    , SYSDATE           
)

mapper.update:
/* isry.sample.mapper.SrvcResrceMngMapper.updateSrvcResrceMngList 공통팀 유민상 */
UPDATE SDA300 SET


     PROGRM_TTL_NM = #{PROGRM_TTL_NM}


    , PROGRM_SE_CD = #{PROGRM_SE_CD}


    , PROGRM_DSCRP_CN = #{PROGRM_DSCRP_CN}


    , PROGRM_DGSTFN_CN = #{PROGRM_DGSTFN_CN}


    , PROGRM_BGNG_YMD = #{PROGRM_BGNG_YMD}


    , PROGRM_END_YMD = #{PROGRM_END_YMD}


    , PROGRM_SUM_HR = #{PROGRM_SUM_HR}


