    , SRVC_RESRCE_MLSFC_SE_CD = #{SRVC_RESRCE_MLSFC_SE_CD}


    , SRVC_RESRCE_SCLAS_SE_CD = #{SRVC_RESRCE_SCLAS_SE_CD}


    , SRVC_RESRCE_DTL_SE_CD = #{SRVC_RESRCE_DTL_SE_CD}


    , RTRCN_YN = #{RTRCN_YN}

